CREATE OR REPLACE FUNCTION public.set_game_paused(p_game_id uuid, p_paused boolean, p_expected_dealer_game_id uuid, p_expected_pause_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_prior_farkle_claim text:=coalesce(current_setting('app.farkle_authority',true),''); v_replay_shared jsonb; v_replay_return jsonb; g public.games%ROWTYPE; now_at timestamptz:=clock_timestamp(); duration interval; remaining integer;
 ctx text; prior jsonb:='{}'; state_row record; shifted jsonb; result jsonb;
BEGIN
 PERFORM private.farkle_require_active_actor_v1(p_game_id,p_expected_dealer_game_id,false);
 IF p_paused IS NULL OR p_expected_pause_version IS NULL THEN RAISE EXCEPTION 'set_game_paused:invalid_request' USING ERRCODE='22023'; END IF;
 -- Taking current round locks first matches the active action owners. NOWAIT
 -- rejects a competing transition for retry instead of creating a lock cycle.
 PERFORM 1 FROM public.rounds WHERE game_id=p_game_id AND dealer_game_id IS NOT DISTINCT FROM p_expected_dealer_game_id
 ORDER BY id FOR UPDATE NOWAIT;
 SELECT * INTO g FROM public.games WHERE id=p_game_id FOR UPDATE NOWAIT;
 IF FOUND THEN
  IF g.replay_contract_version=1 THEN v_replay_shared:=private.replay_gin_lifecycle_begin_v2(g,'public.set_game_paused',true); END IF;
  PERFORM 1; -- Preserve the preceding SELECT's FOUND value for its original guard.
 END IF;
 IF NOT FOUND THEN v_replay_return := jsonb_build_object('outcome','missing_game');
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_paused',p_paused,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_pause_version',p_expected_pause_version),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return; END IF;
 IF coalesce(auth.jwt()->>'role','')<>'service_role' AND (auth.uid() IS NULL OR (
 NOT public.has_role(auth.uid(),'admin'::public.app_role) AND (
 g.current_host IS DISTINCT FROM auth.uid() OR NOT EXISTS(SELECT 1 FROM public.players WHERE game_id=g.id AND user_id=auth.uid()
 AND NOT is_bot AND position IS NOT NULL AND status NOT IN ('left','observer')))))
 THEN v_replay_return := jsonb_build_object('outcome','not_authorized');
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_paused',p_paused,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_pause_version',p_expected_pause_version),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return; END IF;
 IF g.current_game_uuid IS DISTINCT FROM p_expected_dealer_game_id OR g.pause_version IS DISTINCT FROM p_expected_pause_version
 OR (g.status IN ('session_ended','completed') AND private.three_five_seven_hidden_round(g.id,true) IS NULL) THEN v_replay_return := jsonb_build_object('outcome','stale_identity');
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_paused',p_paused,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_pause_version',p_expected_pause_version),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return; END IF;
 IF coalesce(g.is_paused,false)=p_paused THEN v_replay_return := jsonb_build_object('outcome','already_set','is_paused',p_paused,'pause_version',g.pause_version);
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_paused',p_paused,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_pause_version',p_expected_pause_version),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return; END IF;
 IF g.game_type='farkle' THEN PERFORM private.farkle_claim_v1(g.id,g.current_game_uuid,NULL,'pause'); END IF;
 FOREACH ctx IN ARRAY ARRAY['app.session_pause_write','app.three_five_seven_authoritative_write','app.cribbage_authoritative_write','app.gin_rummy_authoritative_write','app.yahtzee_authoritative_write'] LOOP
  prior:=prior||jsonb_build_object(ctx,coalesce(current_setting(ctx,true),''));
  PERFORM set_config(ctx,'on',true); END LOOP;
 IF p_paused THEN
  SELECT greatest(0,ceil(extract(epoch FROM (min(due_at)-now_at))))::integer INTO remaining
  FROM private.game_timer_registry WHERE game_id=g.id AND state='scheduled';
  IF private.three_five_seven_hidden_round(g.id,true) IS NOT NULL THEN
    SELECT greatest(0,ceil(extract(epoch FROM ((private.three_five_seven_decision_reveal(
      r.game_id,r.dealer_game_id,r.id,r.hand_number,r.round_number)->>'drop_at')::timestamptz-now_at))))::integer
    INTO remaining FROM public.rounds r WHERE r.id=private.three_five_seven_hidden_round(g.id,true);
   END IF;
   UPDATE public.games SET is_paused=true,timer_paused_at=now_at,paused_time_remaining=remaining WHERE id=g.id RETURNING pause_version INTO g.pause_version;
  result:=jsonb_build_object('outcome','paused','is_paused',true,'paused_at',now_at,'remaining_seconds',remaining,'pause_version',g.pause_version);
 ELSE
  IF g.timer_paused_at IS NULL THEN RAISE EXCEPTION 'set_game_paused:missing_pause_identity'; END IF;
  duration:=greatest(interval '0 seconds',now_at-g.timer_paused_at);
  UPDATE public.games SET config_deadline=config_deadline+duration,ante_decision_deadline=ante_decision_deadline+duration,
   game_over_at=CASE WHEN status='game_over' THEN game_over_at+duration ELSE game_over_at END,
   dealer_selection_state=CASE WHEN status='cribbage_dealer_selection'
    THEN private.shift_pause_timestamp(dealer_selection_state,ARRAY['preparedAt'],duration) ELSE dealer_selection_state END
  WHERE id=g.id;
  UPDATE public.rounds SET decision_deadline=decision_deadline+duration,presentation_fallback_at=presentation_fallback_at+duration,
   farkle_state=private.shift_pause_timestamp(farkle_state,ARRAY['turnDeadline'],duration),
   horses_state=private.shift_pause_timestamp(horses_state,ARRAY['turnDeadline'],duration),
   yahtzee_state=private.shift_pause_timestamp(yahtzee_state,ARRAY['turnDeadline'],duration)
  WHERE game_id=g.id AND dealer_game_id IS NOT DISTINCT FROM g.current_game_uuid
   AND (status<>'completed' OR presentation_fallback_at IS NOT NULL);
  UPDATE private.three_five_seven_round_resolutions SET presentation_fallback_at=presentation_fallback_at+duration
  WHERE game_id=g.id AND dealer_game_id IS NOT DISTINCT FROM g.current_game_uuid AND presentation_fallback_at IS NOT NULL;
  FOR state_row IN SELECT a.* FROM private.gin_rummy_round_states a JOIN public.rounds r ON r.id=a.round_id
   WHERE r.game_id=g.id AND r.dealer_game_id=g.current_game_uuid AND r.hand_number=g.total_hands LOOP
   shifted:=private.shift_pause_timestamp(state_row.state,ARRAY['scoringDueAt'],duration);
   shifted:=private.shift_pause_timestamp(shifted,ARRAY['completeDueAt'],duration);
   shifted:=private.shift_pause_timestamp(shifted,ARRAY['botActionDueAt'],duration);
   UPDATE private.gin_rummy_round_states SET state=shifted,version=version+1,updated_at=state_row.updated_at+duration WHERE round_id=state_row.round_id;
   UPDATE public.rounds SET gin_rummy_state=private.gin_public_state(shifted) WHERE id=state_row.round_id;
  END LOOP;
  FOR state_row IN SELECT a.* FROM private.cribbage_round_states a JOIN public.rounds r ON r.id=a.round_id
   WHERE r.game_id=g.id AND r.dealer_game_id=g.current_game_uuid AND r.hand_number=g.total_hands LOOP
   shifted:=private.shift_pause_timestamp(state_row.state,ARRAY['countingResolution','presentationReleaseAt'],duration);
   shifted:=private.shift_pause_timestamp(shifted,ARRAY['countingResolution','presentationFallbackAt'],duration);
   IF shifted IS DISTINCT FROM state_row.state THEN
    UPDATE private.cribbage_round_states SET state=shifted,version=version+1 WHERE round_id=state_row.round_id;
    UPDATE public.rounds SET cribbage_state=private.cribbage_public_state(shifted) WHERE id=state_row.round_id;
   END IF;
  END LOOP;
  -- These dealer-draw timers have no separate source deadline column.
  UPDATE private.game_timer_registry SET due_at=due_at+duration,updated_at=now_at WHERE game_id=g.id AND state='scheduled'
   AND timer_kind IN ('dealer_selection_prepare','dealer_selection_complete');
  UPDATE public.games SET is_paused=false,timer_paused_at=NULL,paused_time_remaining=NULL WHERE id=g.id RETURNING pause_version INTO g.pause_version;
  result:=jsonb_build_object('outcome','resumed','is_paused',false,'paused_duration_seconds',extract(epoch FROM duration),'pause_version',g.pause_version);
 END IF;
 FOREACH ctx IN ARRAY ARRAY['app.session_pause_write','app.three_five_seven_authoritative_write','app.cribbage_authoritative_write','app.gin_rummy_authoritative_write','app.yahtzee_authoritative_write'] LOOP
  PERFORM set_config(ctx,prior->>ctx,true); END LOOP;
 v_replay_return := result;
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_paused',p_paused,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_pause_version',p_expected_pause_version),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
EXCEPTION WHEN lock_not_available THEN v_replay_return := jsonb_build_object('outcome','busy');
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_paused',p_paused,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_pause_version',p_expected_pause_version),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_premium(square integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE r int:=square/15;c int:=square%15;
BEGIN
 IF (r IN(0,14) AND c IN(0,7,14)) OR (r=7 AND c IN(0,14)) THEN RETURN 'TW';END IF;
 IF (r=c OR r+c=14) AND (r BETWEEN 1 AND 4 OR r BETWEEN 10 AND 13 OR r=7) THEN RETURN 'DW';END IF;
 IF (r IN(1,13) AND c IN(5,9)) OR (r IN(5,9) AND c IN(1,5,9,13)) THEN RETURN 'TL';END IF;
 IF (r IN(0,14) AND c IN(3,11)) OR (r IN(2,12) AND c IN(6,8)) OR (r IN(3,11) AND c IN(0,7,14)) OR (r IN(6,8) AND c IN(2,6,8,12)) OR (r=7 AND c IN(3,11)) THEN RETURN 'DL';END IF;
 RETURN '';
END $function$

CREATE OR REPLACE FUNCTION public.set_game_paused(p_game_id uuid, p_paused boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g public.games%ROWTYPE;
BEGIN
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN RAISE EXCEPTION 'set_game_paused:version_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO g FROM public.games WHERE id=p_game_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('outcome','missing_game'); END IF;
 RETURN public.set_game_paused(g.id,p_paused,g.current_game_uuid,g.pause_version);
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_deal(s jsonb, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE bag jsonb; racks jsonb:='{}';scores jsonb:='{}';p jsonb; rack jsonb; i int;start_i int;draws jsonb:='[]';letter text;best text; tied int[]; candidates int[];
BEGIN
 IF s->'rules' IS DISTINCT FROM private.ptown_words_rules() THEN RAISE EXCEPTION 'ptown_words:rules';END IF;
 SELECT private.ptown_words_shuffle(jsonb_agg(jsonb_build_object('id',id,'face',face,'value',private.ptown_words_value(face)))) INTO bag FROM (
 SELECT row_number() OVER(ORDER BY dist.letter,n)-1 id,dist.letter face FROM (VALUES('A',9),('B',2),('C',2),('D',4),('E',12),('F',2),('G',3),('H',2),('I',9),('J',1),('K',1),('L',4),('M',2),('N',6),('O',8),('P',2),('Q',1),('R',6),('S',4),('T',6),('U',4),('V',2),('W',2),('X',1),('Y',2),('Z',1),('?',2)) dist(letter,copies) CROSS JOIN LATERAL generate_series(1,copies)n) tiles;
 SELECT array_agg(n) INTO candidates FROM generate_series(0,jsonb_array_length(s->'players')-1)n;
 -- Initial draw determines the starter; blank precedes A. Tied players redraw.
 LOOP
  best:=NULL;tied:=ARRAY[]::int[];bag:=private.ptown_words_shuffle(bag);
  FOR i IN 1..cardinality(candidates) LOOP
   letter:=bag->(i-1)->>'face';draws:=draws||jsonb_build_array(jsonb_build_object('playerId',s->'players'->candidates[i]->>'id','letter',letter));
   IF best IS NULL OR letter COLLATE "C" < best COLLATE "C" THEN best:=letter;tied:=ARRAY[candidates[i]];
   ELSIF letter=best THEN tied:=array_append(tied,candidates[i]);END IF;
  END LOOP;
  EXIT WHEN cardinality(tied)=1;candidates:=tied;
 END LOOP;
 start_i:=tied[1];bag:=private.ptown_words_shuffle(bag);
 FOR p IN SELECT value FROM jsonb_array_elements(s->'players') LOOP
  SELECT jsonb_agg(value ORDER BY ordinal) INTO rack FROM jsonb_array_elements(bag) WITH ORDINALITY t(value,ordinal) WHERE ordinal<=7;
  SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]'::jsonb) INTO bag FROM jsonb_array_elements(bag) WITH ORDINALITY t(value,ordinal) WHERE ordinal>7;
  racks:=racks||jsonb_build_object(p->>'id',rack);scores:=scores||jsonb_build_object(p->>'id',0);
 END LOOP;
 RETURN s||jsonb_build_object('phase','playing','board',(SELECT jsonb_agg(NULL::text) FROM generate_series(1,225)),'bag',bag,'racks',racks,'scores',scores,'turnIndex',start_i,'turn',1,'passes',0,'deadline',at_ms+180000,'openingDraws',draws,'moves','[]'::jsonb,'event',jsonb_build_object('label','Game started','points',0));
END $function$

CREATE OR REPLACE FUNCTION public.ptown_words_snapshot(p_dealer_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.ptown_words_matches; viewer uuid; paused boolean; balances jsonb; batch public.gameplay_transfer_batches; result_id uuid;
BEGIN
 SELECT * INTO STRICT m FROM private.ptown_words_matches WHERE dealer_game_id=p_dealer_game_id;
 SELECT id INTO viewer FROM public.players WHERE game_id=m.game_id AND user_id=auth.uid() AND (status<>'left' OR m.finished) AND NOT is_bot;
 IF viewer IS NULL OR NOT private.ptown_words_actor_allowed(auth.uid()) THEN RAISE EXCEPTION 'ptown_words:membership_required' USING ERRCODE='42501'; END IF;
 SELECT is_paused INTO paused FROM public.games WHERE id=m.game_id;
 IF m.settlement IS NOT NULL THEN
  SELECT jsonb_object_agg(player_id::text,chips) INTO balances FROM public.session_player_snapshots WHERE dealer_game_id=p_dealer_game_id;
 ELSE SELECT jsonb_object_agg(id::text,chips) INTO balances FROM public.players WHERE game_id=m.game_id;END IF;
 SELECT * INTO batch FROM public.gameplay_transfer_batches WHERE dealer_game_id=p_dealer_game_id ORDER BY cursor DESC LIMIT 1;
 SELECT id INTO result_id FROM public.game_results WHERE dealer_game_id=p_dealer_game_id AND settlement_key='ptown_words_terminal';
 RETURN private.ptown_words_visible(m.state,viewer::text)||jsonb_build_object('revision',m.revision,'viewerId',viewer,
  'canAct',NOT coalesce(paused,false) AND m.state->>'phase'<>'complete' AND m.state->'players'->(m.state->>'turnIndex')::integer->>'id'=viewer::text,
  'serverAt',floor(extract(epoch FROM clock_timestamp())*1000),'settlement',m.settlement,'paused',coalesce(paused,false),'finished',m.finished,'pausedAt',m.paused_at,'financial',jsonb_build_object('balances',coalesce(balances,'{}'::jsonb),'resultId',result_id,'batch',CASE WHEN batch.id IS NOT NULL THEN to_jsonb(batch) ELSE NULL END))
  -- Add new presentation metadata only with a newly committed result/revision.
  -- Existing clients compare equal revisions strictly; installation alone must not change their snapshot shape.
  ||CASE WHEN m.state->>'phase'='stage_complete' AND (m.state->'stages'->-1) ? 'id' THEN jsonb_build_object('pausedAt',m.paused_at) ELSE '{}'::jsonb END;
END $function$

CREATE OR REPLACE FUNCTION public.ptown_words_action(p_dealer_game_id uuid, p_request_id uuid, p_revision bigint, p_action text, p_items jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.ptown_words_matches;g public.games;actor uuid:=auth.uid();player uuid;prior private.ptown_words_requests;
 command jsonb:=jsonb_build_object('revision',p_revision,'action',p_action,'items',p_items);at_ms bigint;answer jsonb;rejection text;
BEGIN
 SELECT * INTO STRICT m FROM private.ptown_words_matches WHERE dealer_game_id=p_dealer_game_id;
 PERFORM 1 FROM public.rounds WHERE id=m.round_id FOR UPDATE;
 SELECT * INTO STRICT g FROM public.games WHERE id=m.game_id FOR UPDATE;
 SELECT * INTO STRICT m FROM private.ptown_words_matches WHERE dealer_game_id=p_dealer_game_id FOR UPDATE;
 SELECT id INTO player FROM public.players WHERE game_id=m.game_id AND user_id=actor AND status<>'left' AND NOT is_bot;
 IF player IS NULL OR NOT private.ptown_words_actor_allowed(actor) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(m.state->'players')p WHERE p->>'id'=player::text) THEN RAISE EXCEPTION 'ptown_words:participant_required' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR p_revision IS NULL OR p_action IS NULL OR p_action NOT IN('place','pass','exchange') OR pg_column_size(command)>8192 THEN RAISE EXCEPTION 'ptown_words:invalid_command';END IF;
 SELECT * INTO prior FROM private.ptown_words_requests WHERE dealer_game_id=p_dealer_game_id AND request_id=p_request_id;
 IF FOUND THEN IF prior.actor<>actor OR prior.command<>command THEN RAISE EXCEPTION 'ptown_words:replay_conflict';END IF;RETURN prior.response;END IF;
 IF g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.game_type IS DISTINCT FROM 'ptown-words' OR g.status<>'in_progress' OR m.finished OR g.is_paused THEN RAISE EXCEPTION 'ptown_words:inactive';END IF;
 IF m.revision<>p_revision THEN RAISE EXCEPTION 'ptown_words:stale_revision';END IF;
 IF m.state->'players'->(m.state->>'turnIndex')::int->>'id' IS DISTINCT FROM player::text THEN RAISE EXCEPTION 'ptown_words:not_your_turn' USING ERRCODE='42501';END IF;
 at_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
 IF at_ms<m.last_request_at+400 THEN RAISE EXCEPTION 'ptown_words:rate_limited';END IF;
 BEGIN m.state:=private.ptown_words_reduce(m.state,p_action,p_items,at_ms);
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM NOT LIKE 'ptown_words:%' THEN RAISE;END IF;rejection:=SQLERRM;
 END;
 IF rejection IS NOT NULL THEN
  answer:=jsonb_build_object('error',rejection,'requestId',p_request_id);
  UPDATE private.ptown_words_matches SET last_request_at=at_ms WHERE dealer_game_id=m.dealer_game_id;
 ELSE
  UPDATE private.ptown_words_matches SET state=m.state,revision=revision+1,last_request_at=at_ms WHERE dealer_game_id=m.dealer_game_id;
  IF m.state->>'phase'='complete' THEN PERFORM private.ptown_words_settle(m.dealer_game_id);END IF;
  answer:=public.ptown_words_snapshot(m.dealer_game_id);
 END IF;
 INSERT INTO private.ptown_words_requests(dealer_game_id,request_id,actor,command,response) VALUES(m.dealer_game_id,p_request_id,actor,command,answer);
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.ptown_words_configure(p_game_id uuid, p_dealer_player_id uuid, p_expected_dealer_position integer, p_game_type text, p_config jsonb, p_expected_config_deadline timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g public.games; d public.players; dg public.dealer_games; r uuid:=gen_random_uuid(); actor uuid:=auth.uid();
 claim private.dealer_game_setup_commits; hash text; stake_i integer; people jsonb; s jsonb; result jsonb; setup_players jsonb;
BEGIN
 IF NOT private.ptown_words_actor_allowed(actor) OR p_game_type IS DISTINCT FROM 'ptown-words' THEN RAISE EXCEPTION 'ptown_words:release_closed' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT g FROM public.games WHERE id=p_game_id FOR UPDATE;
 IF g.real_money IS DISTINCT FROM false THEN RAISE EXCEPTION 'ptown_words:fake_money_only' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT d FROM public.players WHERE id=p_dealer_player_id AND game_id=g.id;
 IF d.user_id IS DISTINCT FROM actor OR d.is_bot THEN RAISE EXCEPTION 'ptown_words:dealer_required' USING ERRCODE='42501';END IF;

 IF coalesce(p_config->>'ante_amount','') !~ '^[1-9][0-9]{0,3}$' OR p_expected_config_deadline IS NULL THEN RAISE EXCEPTION 'ptown_words:config';END IF;stake_i:=(p_config->>'ante_amount')::integer;
 hash:=md5(jsonb_build_array(p_game_id,p_dealer_player_id,p_expected_dealer_position,p_config,p_expected_config_deadline)::text);
 SELECT * INTO claim FROM private.dealer_game_setup_commits WHERE game_id=g.id AND expected_config_deadline=p_expected_config_deadline AND expected_dealer_position=p_expected_dealer_position;
 IF FOUND THEN
  IF claim.request_hash<>hash THEN RAISE EXCEPTION 'ptown_words:setup_replay_conflict';END IF;
  IF g.current_game_uuid IS DISTINCT FROM claim.dealer_game_id THEN RAISE EXCEPTION 'ptown_words:setup_retired';END IF;
  RETURN claim.result||'{"outcome":"already_configured","deduped":true}'::jsonb;
 END IF;
 -- Admission controls creation only; existing setup retries and match authority remain live.
 IF NOT EXISTS(SELECT 1 FROM private.ptown_words_release WHERE singleton AND admission_enabled) THEN RAISE EXCEPTION 'ptown_words:admission_closed' USING ERRCODE='42501';END IF;
 IF d.user_id<>actor OR d.is_bot OR d.sitting_out OR d.status<>'active' OR d.position<>p_expected_dealer_position
 OR g.dealer_position IS DISTINCT FROM p_expected_dealer_position OR g.status NOT IN ('game_selection','configuring')
 OR g.config_deadline IS DISTINCT FROM p_expected_config_deadline OR clock_timestamp()>g.config_deadline OR g.is_paused OR g.pending_session_end THEN RAISE EXCEPTION 'ptown_words:setup_identity';END IF;
 PERFORM 1 FROM public.players WHERE game_id=g.id ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.players WHERE game_id=g.id AND status<>'left' AND NOT is_bot AND NOT private.ptown_words_actor_allowed(user_id)) THEN RAISE EXCEPTION 'ptown_words:tester_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.players WHERE game_id=g.id AND status='active' AND NOT sitting_out AND NOT waiting AND position IS NOT NULL AND NOT is_bot) THEN RAISE EXCEPTION 'ptown_words:human_required';END IF;
 SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.user_id,'name',coalesce(pr.username,'Player'),'seat',p.position,'isBot',p.is_bot)
 ORDER BY CASE WHEN p.position<g.dealer_position THEN 0 ELSE 1 END,p.position DESC,p.id) INTO people
 FROM public.players p LEFT JOIN public.profiles pr ON pr.id=p.user_id WHERE p.game_id=g.id AND p.status='active' AND NOT p.sitting_out AND NOT p.waiting AND p.position IS NOT NULL;
 IF coalesce(jsonb_array_length(people),0) NOT BETWEEN 2 AND 4 THEN RAISE EXCEPTION 'ptown_words:player_count';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(people)p WHERE (p->>'isBot')::boolean) AND (g.real_money IS DISTINCT FROM false OR NOT EXISTS(SELECT 1 FROM private.ptown_words_release WHERE singleton AND bots_enabled)) THEN RAISE EXCEPTION 'ptown_words:bots_fake_money_only';END IF;
 IF coalesce(g.pot,0)<>0 THEN RAISE EXCEPTION 'ptown_words:unfinished_pot';END IF;
 -- Established setup-authority handoff flags, scoped to this validated RPC.
 PERFORM set_config('app.cribbage_authoritative_write','on',true);
 PERFORM set_config('app.gin_rummy_authoritative_write','on',true);
 PERFORM set_config('app.three_five_seven_authoritative_write','on',true);
 PERFORM set_config('app.yahtzee_authoritative_write','on',true);
 IF g.game_type='farkle' THEN PERFORM private.farkle_claim_v1(g.id,g.current_game_uuid,NULL,'configure');END IF;
 INSERT INTO public.dealer_games(session_id,dealer_user_id,game_type,config) VALUES(g.id,actor,'ptown-words',jsonb_build_object('ante_amount',stake_i,'rules',private.ptown_words_rules(),'presentation',private.ptown_words_presentation_config())) RETURNING * INTO dg;
 UPDATE public.players SET ante_decision=CASE WHEN id=p_dealer_player_id THEN 'ante_up' ELSE NULL END,current_decision=NULL,decision_locked=false,auto_fold=false WHERE game_id=g.id AND id IN(SELECT (p->>'id')::uuid FROM jsonb_array_elements(people) p);
 UPDATE public.games SET game_type='ptown-words',current_game_uuid=dg.id,config_complete=true,config_deadline=NULL,ante_decision_deadline=clock_timestamp()+make_interval(secs=>greatest(1,coalesce(g.ante_decision_timer_seconds,30))),status='ante_decision',ante_amount=stake_i,current_round=NULL,total_hands=0,replay_contract_version=NULL,all_decisions_in=false,all_decisions_in_round_id=NULL WHERE id=g.id RETURNING * INTO g;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY position) INTO setup_players FROM public.players p WHERE game_id=g.id;
 result:=jsonb_build_object('outcome','configured','deduped',false,'setup_identity',jsonb_build_object('game_id',g.id,'dealer_position',p_expected_dealer_position,'expected_config_deadline',p_expected_config_deadline),'game',to_jsonb(g),'dealer_game',to_jsonb(dg),'players',setup_players);
 INSERT INTO private.dealer_game_setup_commits(game_id,expected_config_deadline,expected_dealer_position,request_hash,dealer_game_id,result) VALUES(g.id,p_expected_config_deadline,p_expected_dealer_position,hash,dg.id,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_finish_postgame(p_dealer_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.ptown_words_matches; g public.games; positions integer[]; next_seat integer; target text; winner uuid; make_take boolean;
BEGIN
 SELECT * INTO STRICT m FROM private.ptown_words_matches WHERE dealer_game_id=p_dealer_game_id;
 PERFORM 1 FROM public.rounds WHERE id=m.round_id FOR UPDATE;
 SELECT * INTO STRICT g FROM public.games WHERE id=m.game_id FOR UPDATE;
 SELECT * INTO STRICT m FROM private.ptown_words_matches WHERE dealer_game_id=p_dealer_game_id FOR UPDATE;
 IF m.settlement IS NULL THEN RAISE EXCEPTION 'ptown_words:close_denied' USING ERRCODE='42501';END IF;
 IF m.finished THEN RETURN;END IF;
 IF coalesce((m.state#>>'{terminal,deadline}')::bigint,0)>floor(extract(epoch FROM clock_timestamp())*1000) THEN RETURN;END IF;
 IF g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.game_type IS DISTINCT FROM 'ptown-words' OR g.status NOT IN ('game_over','session_ended') THEN RAISE EXCEPTION 'ptown_words:close_identity';END IF;
 IF g.status<>'session_ended' THEN
  PERFORM 1 FROM public.players WHERE game_id=m.game_id ORDER BY id FOR UPDATE;
  UPDATE public.players SET status=CASE WHEN stand_up_next_hand THEN 'left' ELSE status END,
   sitting_out=CASE WHEN stand_up_next_hand OR sit_out_next_hand THEN true WHEN waiting THEN false ELSE sitting_out END,
   waiting=false,stand_up_next_hand=false,sit_out_next_hand=false,auto_fold=false,auto_play_stop_round_id=NULL,
   current_decision=NULL,decision_locked=false,pre_fold=false,pre_stay=false,ante_decision=NULL,auto_ante=false,auto_ante_runback=false WHERE game_id=m.game_id;
  IF g.pending_session_end THEN target:='session_ended';
  ELSIF (SELECT count(*) FROM public.players WHERE game_id=m.game_id AND status NOT IN ('left','observer') AND NOT sitting_out AND position IS NOT NULL)<2 THEN
   PERFORM private.resolve_postgame_participation(m.game_id,clock_timestamp());SELECT status INTO target FROM public.games WHERE id=m.game_id;
  ELSE
   SELECT array_agg(position ORDER BY position DESC) INTO positions FROM public.players WHERE game_id=m.game_id AND status NOT IN ('left','observer') AND NOT sitting_out AND position IS NOT NULL AND NOT is_bot;
   SELECT coalesce((value->>'enabled')::boolean,false) INTO make_take FROM public.system_settings WHERE key='make_it_take_it';
   IF coalesce(make_take,false) THEN
    SELECT winner_player_id INTO winner FROM public.game_results WHERE dealer_game_id=m.dealer_game_id AND settlement_key='ptown_words_terminal';
    SELECT position INTO next_seat FROM public.players WHERE id=winner AND game_id=m.game_id AND NOT is_bot AND NOT sitting_out AND status NOT IN ('left','observer') AND position IS NOT NULL;
    IF next_seat IS NULL THEN IF cardinality(positions)=1 THEN next_seat:=positions[1];ELSE target:='dealer_selection';END IF;END IF;
   END IF;
   IF target IS NULL THEN
    IF next_seat IS NULL THEN SELECT max(p) INTO next_seat FROM unnest(positions) p WHERE p<g.dealer_position;next_seat:=coalesce(next_seat,positions[1]);END IF;
    target:=CASE WHEN next_seat IS NULL THEN 'dealer_selection' ELSE 'game_selection' END;
   END IF;
  END IF;
  UPDATE public.games SET status=target,game_type=CASE WHEN target='session_ended' THEN game_type END,
   current_game_uuid=NULL,config_complete=false,current_round=NULL,total_hands=0,all_decisions_in=false,all_decisions_in_round_id=NULL,
   last_round_result=NULL,awaiting_next_round=false,next_round_number=NULL,game_over_at=NULL,pot=0,
   ante_decision_deadline=NULL,buck_position=NULL,is_first_hand=false,dealer_selection_state=NULL,
   dealer_position=coalesce(next_seat,dealer_position),config_deadline=CASE WHEN target='game_selection' THEN clock_timestamp()+make_interval(secs=>greatest(1,game_setup_timer_seconds)) END,
   pending_session_end=CASE WHEN target='session_ended' THEN false ELSE pending_session_end END,
   session_ended_at=CASE WHEN target='session_ended' THEN coalesce(session_ended_at,clock_timestamp()) ELSE session_ended_at END WHERE id=m.game_id;
 END IF;
 UPDATE private.ptown_words_matches SET finished=true,revision=revision+1 WHERE dealer_game_id=m.dealer_game_id;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_pause()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE at_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000);
BEGIN
 IF NEW.game_type IS DISTINCT FROM 'ptown-words' OR NEW.is_paused IS NOT DISTINCT FROM OLD.is_paused THEN RETURN NEW;END IF;
 IF NEW.is_paused THEN UPDATE private.ptown_words_matches SET paused_at=at_ms,revision=revision+1 WHERE dealer_game_id=NEW.current_game_uuid AND settlement IS NULL;
 ELSE UPDATE private.ptown_words_matches SET state=state||jsonb_build_object('deadline',(state->>'deadline')::bigint+at_ms-paused_at)||CASE WHEN state ? 'startedAt' THEN jsonb_build_object('startedAt',(state->>'startedAt')::bigint+at_ms-paused_at) ELSE '{}'::jsonb END,paused_at=NULL,revision=revision+1 WHERE dealer_game_id=NEW.current_game_uuid AND paused_at IS NOT NULL AND settlement IS NULL;END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_reduce(s jsonb, action text, items jsonb, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
<<reducer>>
DECLARE board jsonb:=s->'board';old_board jsonb:=board;bag jsonb:=s->'bag';player text:=s->'players'->(s->>'turnIndex')::int->>'id';rack jsonb:=s->'racks'->player;
 used int[]:=ARRAY[]::int[];squares int[]:=ARRAY[]::int[];tile jsonb;item jsonb;cell jsonb;letter text;sq int;i int;j int;k int;r int;c int;dr int;dc int;rr int;cc int;start_r int;start_c int;direction int;seen text[]:=ARRAY[]::text[];key text;word text;words jsonb:='[]';points int:=0;subtotal int;multiplier int;value_i int;premium text;connected boolean:=false;empty_board boolean;rows int[];cols int[];score_before jsonb;deductions jsonb:='{}';deduct int;total_deduct int:=0;person jsonb;went_out boolean:=false;done boolean:=false;count_i int;discard jsonb:='[]';label text;winners jsonb;best int;prebest int;
BEGIN
 IF s#>>'{rules,version}'<>'ptown-words/1' OR s->'rules' IS DISTINCT FROM private.ptown_words_rules() THEN RAISE EXCEPTION 'ptown_words:rules';END IF;
 IF s->>'phase'<>'playing' THEN RAISE EXCEPTION 'ptown_words:phase';END IF;
 IF action='tick' THEN IF at_ms<(s->>'deadline')::bigint THEN RETURN s;END IF;action:='pass';
 ELSIF at_ms>=(s->>'deadline')::bigint THEN RAISE EXCEPTION 'ptown_words:deadline';END IF;
 IF action<>'tick' AND at_ms<coalesce((s#>>'{movePresentation,readyAt}')::bigint,0) THEN RAISE EXCEPTION 'ptown_words:presenting_move';END IF;
 IF action NOT IN('place','exchange','pass') THEN RAISE EXCEPTION 'ptown_words:invalid_action';END IF;
 IF action IN('place','exchange') THEN
  IF jsonb_typeof(items) IS DISTINCT FROM 'array' OR jsonb_array_length(items) NOT BETWEEN 1 AND 7 THEN RAISE EXCEPTION 'ptown_words:invalid_tiles';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
   IF jsonb_typeof(item->'tileId') IS DISTINCT FROM 'number' OR (item->>'tileId') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'ptown_words:tile_id';END IF;
   i:=(item->>'tileId')::int;
   SELECT value INTO tile FROM jsonb_array_elements(rack) WHERE (value->>'id')::int=i;
   IF tile IS NULL OR i=ANY(used) THEN RAISE EXCEPTION 'ptown_words:tile_not_owned';END IF;used:=array_append(used,i);discard:=discard||jsonb_build_array(tile);
   IF action='place' THEN
    IF jsonb_typeof(item->'square') IS DISTINCT FROM 'number' OR (item->>'square') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'ptown_words:square';END IF;
    sq:=(item->>'square')::int;
    IF sq NOT BETWEEN 0 AND 224 OR sq=ANY(squares) OR board->sq IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'ptown_words:occupied_square';END IF;
    letter:=item->>'letter';IF letter IS NULL OR letter !~ '^[A-Z]$' OR (tile->>'face'<>'?' AND letter<>tile->>'face') THEN RAISE EXCEPTION 'ptown_words:blank_letter';END IF;
    squares:=array_append(squares,sq);board:=jsonb_set(board,ARRAY[sq::text],tile||jsonb_build_object('letter',letter,'blank',tile->>'face'='?'));
   END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]'::jsonb) INTO rack FROM jsonb_array_elements(rack) WITH ORDINALITY t(value,ordinal) WHERE NOT (value->>'id')::int=ANY(used);
 END IF;
 IF action='place' THEN
  SELECT array_agg(DISTINCT x/15),array_agg(DISTINCT x%15) INTO rows,cols FROM unnest(squares)x;
  IF cardinality(rows)>1 AND cardinality(cols)>1 THEN RAISE EXCEPTION 'ptown_words:one_line';END IF;
  empty_board:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements(old_board)v WHERE v<>'null'::jsonb);
  IF empty_board AND NOT 112=ANY(squares) THEN RAISE EXCEPTION 'ptown_words:cover_center';END IF;
  IF cardinality(rows)=1 THEN FOR i IN (SELECT min(x%15) FROM unnest(squares)x)..(SELECT max(x%15) FROM unnest(squares)x) LOOP IF board->(rows[1]*15+i)='null'::jsonb THEN RAISE EXCEPTION 'ptown_words:gap';END IF;END LOOP;
  ELSE FOR i IN (SELECT min(x/15) FROM unnest(squares)x)..(SELECT max(x/15) FROM unnest(squares)x) LOOP IF board->(i*15+cols[1])='null'::jsonb THEN RAISE EXCEPTION 'ptown_words:gap';END IF;END LOOP;END IF;
  FOREACH sq IN ARRAY squares LOOP
   r:=sq/15;c:=sq%15;
   IF (r>0 AND old_board->(sq-15)<>'null'::jsonb) OR (r<14 AND old_board->(sq+15)<>'null'::jsonb) OR (c>0 AND old_board->(sq-1)<>'null'::jsonb) OR (c<14 AND old_board->(sq+1)<>'null'::jsonb) THEN connected:=true;END IF;
   FOR direction IN 0..1 LOOP
    dr:=direction;dc:=1-direction;rr:=r;cc:=c;
    WHILE rr-dr>=0 AND cc-dc>=0 AND board->((rr-dr)*15+cc-dc)<>'null'::jsonb LOOP rr:=rr-dr;cc:=cc-dc;END LOOP;
    start_r:=rr;start_c:=cc;key:=rr||':'||cc||':'||direction;IF key=ANY(seen) THEN CONTINUE;END IF;seen:=array_append(seen,key);
    word:='';subtotal:=0;multiplier:=1;
    WHILE rr<15 AND cc<15 AND board->(rr*15+cc)<>'null'::jsonb LOOP
     k:=rr*15+cc;cell:=board->k;word:=word||(cell->>'letter');value_i:=(cell->>'value')::int;
     IF k=ANY(squares) THEN premium:=private.ptown_words_premium(k);IF premium='DL' THEN value_i:=value_i*2;ELSIF premium='TL' THEN value_i:=value_i*3;ELSIF premium='DW' THEN multiplier:=multiplier*2;ELSIF premium='TW' THEN multiplier:=multiplier*3;END IF;END IF;
     subtotal:=subtotal+value_i;rr:=rr+dr;cc:=cc+dc;
    END LOOP;
    IF length(word)>1 THEN
     IF NOT EXISTS(SELECT 1 FROM private.ptown_words_lexicon l WHERE l.version=s#>>'{rules,dictionaryId}' AND l.word=reducer.word) THEN RAISE EXCEPTION 'ptown_words:invalid_word:%',word;END IF;
     points:=points+subtotal*multiplier;words:=words||jsonb_build_array(jsonb_build_object('word',word,'points',subtotal*multiplier,'square',start_r*15+start_c,'direction',direction));
    END IF;
   END LOOP;
  END LOOP;
  IF (NOT empty_board AND NOT connected) OR jsonb_array_length(words)=0 THEN RAISE EXCEPTION 'ptown_words:disconnected';END IF;
  IF cardinality(squares)=7 THEN points:=points+50;END IF;
  s:=jsonb_set(s,ARRAY['scores',player],to_jsonb((s->'scores'->>player)::int+points));
  s:=s||jsonb_build_object('board',board,'passes',0);label:=(words->0->>'word');
 ELSIF action='exchange' THEN
  IF jsonb_array_length(bag)<7 THEN RAISE EXCEPTION 'ptown_words:need_seven_in_bag';END IF;
  s:=s||jsonb_build_object('passes',0);label:='Exchanged '||cardinality(used)||' tiles';
 ELSE s:=s||jsonb_build_object('passes',(s->>'passes')::int+1);label:='Passed';END IF;
 IF action IN('place','exchange') THEN
  count_i:=least(7-jsonb_array_length(rack),jsonb_array_length(bag));
  FOR i IN 1..count_i LOOP rack:=rack||jsonb_build_array(bag->0);bag:=bag-0;END LOOP;
  IF action='exchange' THEN bag:=private.ptown_words_shuffle(bag||discard);END IF;
 END IF;
 s:=jsonb_set(s,ARRAY['racks',player],rack)||jsonb_build_object('bag',bag);
 went_out:=action='place' AND jsonb_array_length(bag)=0 AND jsonb_array_length(rack)=0;
 done:=went_out OR (s->>'passes')::int>=2*jsonb_array_length(s->'players');
 s:=s||jsonb_build_object('moves',(s->'moves')||jsonb_build_array(jsonb_build_object('turn',(s->>'turn')::int,'playerId',player,'action',action,'words',words,'count',coalesce(cardinality(used),0),'points',points)),'event',jsonb_build_object('label',label,'points',points),'turn',(s->>'turn')::int+1);
 IF done THEN
  score_before:=s->'scores';
  FOR person IN SELECT value FROM jsonb_array_elements(s->'players') LOOP
   SELECT coalesce(sum((v->>'value')::int),0) INTO deduct FROM jsonb_array_elements(s->'racks'->(person->>'id'))v;
   deductions:=deductions||jsonb_build_object(person->>'id',deduct);total_deduct:=total_deduct+deduct;
   s:=jsonb_set(s,ARRAY['scores',person->>'id'],to_jsonb((s->'scores'->>(person->>'id'))::int-deduct));
  END LOOP;
  IF went_out THEN s:=jsonb_set(s,ARRAY['scores',player],to_jsonb((s->'scores'->>player)::int+total_deduct));END IF;
  SELECT max(value::int) INTO best FROM jsonb_each_text(s->'scores');
  SELECT max((score_before->>x.key)::int) INTO prebest FROM jsonb_each_text(s->'scores')x WHERE x.value::int=best;
  SELECT jsonb_agg(x.key ORDER BY x.key) INTO winners FROM jsonb_each_text(s->'scores')x WHERE x.value::int=best AND (score_before->>x.key)::int=prebest;
  RETURN s||jsonb_build_object('phase','complete','deadline',0,'winnerIds',winners,'preAdjustmentScores',score_before,'rackDeductions',deductions,'endReason',CASE WHEN went_out THEN 'rack_empty' ELSE 'passes' END);
 END IF;
 RETURN s||jsonb_build_object('turnIndex',((s->>'turnIndex')::int+1)%jsonb_array_length(s->'players'),'deadline',at_ms+180000);
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_settle(p_dealer_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.ptown_words_matches; g public.games; winners uuid[]; win_count integer; total integer; deltas jsonb; transfers jsonb:='[]';
 result_id uuid; player jsonb; winner uuid; loser uuid; amount integer; changes jsonb:='{}'; allocated integer;
BEGIN
 SELECT * INTO STRICT m FROM private.ptown_words_matches WHERE dealer_game_id=p_dealer_game_id FOR UPDATE;
 IF m.settlement IS NOT NULL THEN RETURN; END IF;
 SELECT * INTO STRICT g FROM public.games WHERE id=m.game_id FOR UPDATE;
 IF g.game_type IS DISTINCT FROM 'ptown-words' OR g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.status<>'in_progress' OR g.is_paused
  OR m.state->>'phase'<>'complete' OR (SELECT count(*) FROM jsonb_object_keys(m.state->'scores'))<>jsonb_array_length(m.state->'players') THEN RAISE EXCEPTION 'ptown_words:not_terminal'; END IF;
 SELECT array_agg(value::uuid ORDER BY value) INTO winners FROM jsonb_array_elements_text(m.state->'winnerIds');
 IF coalesce(cardinality(winners),0)=0 THEN RAISE EXCEPTION 'ptown_words:missing_winners';END IF;
 win_count:=cardinality(winners);total:=(jsonb_array_length(m.state->'players')-win_count)*m.stake;
 deltas:=private.split_whole_chips_clockwise(m.game_id,winners,total,g.dealer_position);
 FOR player IN SELECT value FROM jsonb_array_elements(m.state->'players') LOOP
  loser:=(player->>'id')::uuid;
  IF NOT loser=ANY(winners) THEN changes:=changes||jsonb_build_object(loser::text,-m.stake); END IF;
 END LOOP;
 changes:=changes||deltas;
 -- Existing signed session chip accounting and transfer journal; no alternate ledger.
 -- Allocate each loser's stake across winners according to the canonical split.
 FOR player IN SELECT value FROM jsonb_array_elements(m.state->'players') LOOP
  loser:=(player->>'id')::uuid;IF loser=ANY(winners) THEN CONTINUE; END IF;allocated:=m.stake;
  FOREACH winner IN ARRAY winners LOOP
   amount:=least(allocated,(deltas->>winner::text)::integer);
   IF amount>0 THEN transfers:=transfers||jsonb_build_array(jsonb_build_object('from',jsonb_build_object('kind','player','playerId',loser),'to',jsonb_build_object('kind','player','playerId',winner),'amount',amount));
    deltas:=jsonb_set(deltas,ARRAY[winner::text],to_jsonb((deltas->>winner::text)::integer-amount));allocated:=allocated-amount;END IF;
  END LOOP;
  IF allocated<>0 THEN RAISE EXCEPTION 'ptown_words:unbalanced_settlement'; END IF;
 END LOOP;
 INSERT INTO public.game_results(game_id,dealer_game_id,hand_number,settlement_key,game_type,winner_player_id,winner_username,winning_hand_description,pot_won,player_chip_changes,is_chopped)
 VALUES(m.game_id,m.dealer_game_id,1,'ptown_words_terminal','ptown-words',CASE WHEN win_count=1 THEN winners[1] END,
  CASE WHEN win_count>1 THEN 'Tie' ELSE (SELECT p->>'name' FROM jsonb_array_elements(m.state->'players') p WHERE p->>'id'=winners[1]::text) END,
  'Ptown Words: '||(m.state->'scores')::text,total,changes,win_count>1) RETURNING id INTO result_id;
 IF jsonb_array_length(transfers)>0 THEN PERFORM public.settle_gameplay_chip_transfers(m.game_id,transfers,'win'); END IF;
 UPDATE public.rounds SET status='completed',decision_deadline=NULL,current_turn_position=NULL WHERE id=m.round_id;
 INSERT INTO public.session_player_snapshots(game_id,dealer_game_id,player_id,user_id,username,chips,is_bot,hand_number)
 SELECT p.game_id,m.dealer_game_id,p.id,p.user_id,coalesce(pr.username,'Player'),p.chips,p.is_bot,1 FROM public.players p LEFT JOIN public.profiles pr ON pr.id=p.user_id WHERE p.game_id=m.game_id
 ON CONFLICT(game_id,dealer_game_id,hand_number,player_id) DO UPDATE SET chips=EXCLUDED.chips,created_at=clock_timestamp();
 UPDATE private.ptown_words_matches SET settlement=changes,revision=revision+1,state=state||jsonb_build_object('terminal',jsonb_build_object('resultId',result_id,'winnerIds',to_jsonb(winners),'score',(SELECT max(value::bigint) FROM jsonb_each_text(m.state->'scores')),'startedAt',greatest(floor(extract(epoch FROM clock_timestamp())*1000)::bigint,coalesce((m.state#>>'{movePresentation,readyAt}')::bigint,0)),'deadline',greatest(floor(extract(epoch FROM clock_timestamp())*1000)::bigint,coalesce((m.state#>>'{movePresentation,readyAt}')::bigint,0))+3000,'achievements','{}'::jsonb)) WHERE dealer_game_id=m.dealer_game_id;
 UPDATE public.games SET status=CASE WHEN pending_session_end THEN 'session_ended' ELSE 'game_over' END,
  session_ended_at=CASE WHEN pending_session_end THEN clock_timestamp() ELSE session_ended_at END,pending_session_end=false,
  game_over_at=clock_timestamp(),last_round_result='Ptown Words complete',awaiting_next_round=false WHERE id=m.game_id;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_recover(p_dealer_game_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE candidate record; m private.ptown_words_matches; g public.games; at_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000); count_i integer:=0; i integer; choice jsonb; actor uuid;
BEGIN
 FOR candidate IN SELECT work.dealer_game_id,work.game_id,work.round_id,work.revision,work.state->>'phase' phase,work.state->>'stage' stage,
   work.state->'players'->(work.state->>'turnIndex')::integer->>'id' player_id
  FROM private.ptown_words_matches work JOIN public.games live ON live.id=work.game_id
  WHERE (p_dealer_game_id IS NULL OR work.dealer_game_id=p_dealer_game_id) AND NOT work.finished AND work.settlement IS NULL AND work.paused_at IS NULL
   AND least((work.state->>'deadline')::bigint,work.bot_due_at)<=at_ms
   AND live.status='in_progress' AND live.game_type='ptown-words'
   AND live.current_game_uuid=work.dealer_game_id AND NOT live.is_paused
  ORDER BY least((work.state->>'deadline')::bigint,work.bot_due_at),work.dealer_game_id LIMIT 2 LOOP
  PERFORM 1 FROM public.rounds WHERE id=candidate.round_id FOR UPDATE SKIP LOCKED;IF NOT FOUND THEN CONTINUE;END IF;
  SELECT * INTO g FROM public.games WHERE id=candidate.game_id FOR UPDATE SKIP LOCKED;
  IF NOT FOUND OR g.is_paused OR g.status<>'in_progress'
   OR g.game_type IS DISTINCT FROM 'ptown-words' OR g.current_game_uuid IS DISTINCT FROM candidate.dealer_game_id THEN CONTINUE;END IF;
  SELECT * INTO m FROM private.ptown_words_matches WHERE dealer_game_id=candidate.dealer_game_id FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE;END IF;
  at_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
  IF m.finished OR m.settlement IS NOT NULL OR m.paused_at IS NOT NULL OR m.revision<>candidate.revision
   OR m.game_id<>candidate.game_id OR m.round_id<>candidate.round_id OR m.state->>'phase' IS DISTINCT FROM candidate.phase
   OR m.state->>'stage' IS DISTINCT FROM candidate.stage
   OR m.state->'players'->(m.state->>'turnIndex')::integer->>'id' IS DISTINCT FROM candidate.player_id
   OR least((m.state->>'deadline')::bigint,m.bot_due_at)>at_ms THEN CONTINUE;END IF;
  IF private.pause_all_humans_auto_fold(g.id) THEN CONTINUE;END IF;
  IF (m.state->>'deadline')::bigint<=at_ms THEN
   m.state:=private.ptown_words_reduce(m.state,'tick',NULL,at_ms);
  ELSE
   actor:=candidate.player_id::uuid;
   IF m.bot_due_at IS NULL OR m.bot_due_at>at_ms
    OR NOT coalesce((m.state->'players'->(m.state->>'turnIndex')::integer->>'isBot')::boolean,false)
    OR NOT EXISTS(SELECT 1 FROM public.players WHERE id=actor AND game_id=m.game_id AND is_bot) THEN CONTINUE;END IF;
   IF g.real_money IS DISTINCT FROM false THEN CONTINUE;END IF;
   choice:=private.ptown_words_bot_choice(private.ptown_words_visible(m.state,actor::text),at_ms);
   IF choice IS NULL THEN CONTINUE;END IF;
   m.state:=private.ptown_words_reduce(m.state,choice->>'action',choice->'items',at_ms);
  END IF;
  UPDATE private.ptown_words_matches SET state=m.state,revision=revision+1 WHERE dealer_game_id=m.dealer_game_id AND revision=candidate.revision;
  IF m.state->>'phase'='complete' THEN PERFORM private.ptown_words_settle(m.dealer_game_id);END IF;
  count_i:=count_i+1;
 END LOOP;
 FOR candidate IN SELECT dealer_game_id FROM private.ptown_words_matches WHERE (p_dealer_game_id IS NULL OR dealer_game_id=p_dealer_game_id) AND NOT finished AND settlement IS NOT NULL AND (state#>>'{terminal,deadline}')::bigint<=at_ms ORDER BY dealer_game_id LIMIT 20 LOOP
 PERFORM private.ptown_words_finish_postgame(candidate.dealer_game_id);count_i:=count_i+1;END LOOP;
 RETURN count_i;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_schedule_bot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.state->'players') p WHERE NOT coalesce((p->>'isBot')::boolean,false)) THEN
  RAISE EXCEPTION 'ptown_words:human_required';
 END IF;
 IF NEW.finished OR NEW.settlement IS NOT NULL OR NEW.paused_at IS NOT NULL
  OR NEW.state->>'phase' NOT IN ('ready','playing')
  OR NOT coalesce((NEW.state->'players'->(NEW.state->>'turnIndex')::integer->>'isBot')::boolean,false) THEN
  NEW.bot_due_at:=NULL;
 ELSIF TG_OP='INSERT' THEN NEW.bot_due_at:=greatest(floor(extract(epoch FROM clock_timestamp())*1000)::bigint,coalesce((NEW.state#>>'{movePresentation,readyAt}')::bigint,0))+750;
 ELSIF OLD.paused_at IS NOT NULL OR NEW.state IS DISTINCT FROM OLD.state THEN
  NEW.bot_due_at:=greatest(floor(extract(epoch FROM clock_timestamp())*1000)::bigint,coalesce((NEW.state#>>'{movePresentation,readyAt}')::bigint,0))+750;
 ELSE NEW.bot_due_at:=OLD.bot_due_at;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_present_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE config jsonb;move jsonb;squares jsonb;at_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000);announce_at bigint;ready_at bigint;delta bigint;
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT dg.config->'presentation' INTO config FROM public.dealer_games dg WHERE dg.id=NEW.dealer_game_id;
  IF config IS NOT NULL THEN NEW.state:=NEW.state||jsonb_build_object('presentationConfig',config);END IF;
  RETURN NEW;
 END IF;
 config:=OLD.state->'presentationConfig';
 IF config IS NULL THEN RETURN NEW;END IF;
 IF NEW.paused_at IS NULL AND OLD.paused_at IS NOT NULL AND (OLD.state#>>'{movePresentation,readyAt}')::bigint>OLD.paused_at THEN
  delta:=at_ms-OLD.paused_at;
  NEW.state:=jsonb_set(NEW.state,'{movePresentation}',(NEW.state->'movePresentation')||jsonb_build_object(
   'startedAt',(OLD.state#>>'{movePresentation,startedAt}')::bigint+delta,
   'announceAt',(OLD.state#>>'{movePresentation,announceAt}')::bigint+delta,
   'readyAt',(OLD.state#>>'{movePresentation,readyAt}')::bigint+delta));
 END IF;
 IF (NEW.state->>'turn')::int<>(OLD.state->>'turn')::int+1 THEN RETURN NEW;END IF;
 NEW.state:=NEW.state-'movePresentation';move:=NEW.state->'moves'->-1;
 IF move->>'action'<>'place' THEN RETURN NEW;END IF;
 SELECT jsonb_agg(i ORDER BY i) INTO squares FROM generate_series(0,224)i WHERE OLD.state->'board'->i='null'::jsonb AND NEW.state->'board'->i<>'null'::jsonb;
 announce_at:=at_ms+(config->>'focusMs')::int+jsonb_array_length(squares)*(config->>'flipMs')::int;
 ready_at:=announce_at+(config->>'noticeMs')::int+(config->>'holdMs')::int;
 NEW.state:=NEW.state||jsonb_build_object('movePresentation',jsonb_build_object('version',1,'turn',move->'turn','playerId',move->'playerId',
  'squares',squares,'startedAt',at_ms,'announceAt',announce_at,'readyAt',ready_at,'flipMs',config->'flipMs','focusMs',config->'focusMs','noticeMs',config->'noticeMs'));
 IF NEW.state->>'phase'='playing' THEN NEW.state:=jsonb_set(NEW.state,'{deadline}',to_jsonb(ready_at+(NEW.state#>>'{rules,turnMs}')::int));END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_bot_choice(visible jsonb, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE board jsonb:=visible->'board';rack jsonb:=visible->'rack';version_i text:=visible#>>'{rules,dictionaryId}';
 player text:=visible->>'activePlayerId';simulation jsonb;trial jsonb;best jsonb;best_cost int:=2147483647;cost_i int;tie_i text;best_tie text:='~';
 starts jsonb:='[]';entry jsonb;stack jsonb[];node jsonb;remaining jsonb;placements jsonb;prefix text;first_word text;
 direction_i int;lane int;offset_i int;start_i int;end_i int;step_i int;position_i int;next_i int;sq int;r int;c int;rr int;cc int;
 empties int;distance_i int;anchor boolean;connected boolean;empty_board boolean;face text;letter text;cross_word text;seen text;
 tile jsonb;tile_i int;letter_i int;nodes int:=0;candidates int:=0;score_i int;rack_count int:=jsonb_array_length(rack);
BEGIN
 IF visible?'bag' OR visible?'racks' THEN RAISE EXCEPTION 'ptown_words:bot_private_input';END IF;
 IF visible->>'phase'<>'playing' OR rack_count=0 THEN RETURN jsonb_build_object('action','pass','items',NULL);END IF;
 empty_board:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements(board)b WHERE b<>'null'::jsonb);
 -- Only the public projection is used to construct trial moves. Empty simulated
 -- opponent racks/bag prevent any hidden draw information reaching the policy.
 -- Read event.points only; the real reducer performs the real draw and endgame.
 simulation:=visible||jsonb_build_object('bag','[]'::jsonb,'racks',(SELECT jsonb_object_agg(p->>'id',CASE WHEN p->>'id'=player THEN rack ELSE '[]'::jsonb END) FROM jsonb_array_elements(visible->'players')p));
 FOR direction_i IN 0..1 LOOP
  step_i:=CASE WHEN direction_i=0 THEN 1 ELSE 15 END;
  FOR lane IN 0..14 LOOP FOR offset_i IN 0..14 LOOP
   start_i:=CASE WHEN direction_i=0 THEN lane*15+offset_i ELSE offset_i*15+lane END;
   end_i:=CASE WHEN direction_i=0 THEN lane*15+14 ELSE 210+lane END;
   IF offset_i>0 AND board->(start_i-step_i)<>'null'::jsonb THEN CONTINUE;END IF;
   empties:=0;anchor:=false;distance_i:=0;
   FOR position_i IN offset_i..14 LOOP
    sq:=start_i+(position_i-offset_i)*step_i;r:=sq/15;c:=sq%15;
    IF board->sq='null'::jsonb THEN empties:=empties+1;END IF;
    EXIT WHEN empties>rack_count;
    IF (empty_board AND sq=112) OR (NOT empty_board AND (board->sq<>'null'::jsonb OR
     (r>0 AND board->(sq-15)<>'null'::jsonb) OR (r<14 AND board->(sq+15)<>'null'::jsonb) OR
     (c>0 AND board->(sq-1)<>'null'::jsonb) OR (c<14 AND board->(sq+1)<>'null'::jsonb))) THEN anchor:=true;EXIT;END IF;
    distance_i:=distance_i+1;
   END LOOP;
   IF anchor THEN starts:=starts||jsonb_build_array(jsonb_build_object('start',start_i,'end',end_i,'step',step_i,'distance',distance_i));END IF;
  END LOOP;END LOOP;
 END LOOP;
 <<search>>
 FOR entry IN SELECT value FROM jsonb_array_elements(starts) ORDER BY (value->>'distance')::int,md5((value->>'start')||':'||(value->>'step')||':'||(visible->>'turn')) LOOP
  step_i:=(entry->>'step')::int;end_i:=(entry->>'end')::int;
  stack:=ARRAY[jsonb_build_object('pos',(entry->>'start')::int,'prefix','','rack',rack,'items','[]'::jsonb,'connected',false)];
  WHILE cardinality(stack)>0 LOOP
   node:=stack[cardinality(stack)];stack:=stack[1:cardinality(stack)-1];nodes:=nodes+1;EXIT search WHEN nodes>3000 OR candidates>=24;
   position_i:=(node->>'pos')::int;prefix:=node->>'prefix';remaining:=node->'rack';placements:=node->'items';connected:=(node->>'connected')::boolean;
   SELECT word INTO first_word FROM private.ptown_words_bot_vocabulary WHERE word>=prefix COLLATE "C" AND word<(prefix||'[') COLLATE "C" ORDER BY word LIMIT 1;
   IF first_word IS NULL THEN CONTINUE;END IF;
   IF first_word=prefix AND length(prefix)>1 AND jsonb_array_length(placements)>0 AND connected AND (position_i>end_i OR board->position_i='null'::jsonb) THEN
    BEGIN
     trial:=private.ptown_words_reduce(simulation,'place',placements,at_ms);score_i:=(trial#>>'{event,points}')::int;candidates:=candidates+1;
     -- Every formed word, including cross-words, must be in the familiar subset.
     IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(trial->'moves'->-1->'words') w WHERE NOT EXISTS(SELECT 1 FROM private.ptown_words_bot_vocabulary k WHERE k.word=w->>'word')) THEN
      cost_i:=abs(score_i-8)*100+length(prefix)*3;
      tie_i:=md5(player||':'||(visible->>'turn')||':'||placements::text);
      IF cost_i<best_cost OR (cost_i=best_cost AND tie_i<best_tie) THEN best_cost:=cost_i;best_tie:=tie_i;best:=jsonb_build_object('action','place','items',placements);END IF;
     END IF;
    EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'ptown_words:%' THEN RAISE;END IF;
    END;
   END IF;
   IF position_i>end_i THEN CONTINUE;END IF;
   next_i:=position_i+step_i;
   IF board->position_i<>'null'::jsonb THEN
    stack:=array_append(stack,node||jsonb_build_object('pos',next_i,'prefix',prefix||(board->position_i->>'letter'),'connected',true));CONTINUE;
   END IF;
   seen:='';r:=position_i/15;c:=position_i%15;
   FOR tile_i IN 0..jsonb_array_length(remaining)-1 LOOP
    tile:=remaining->tile_i;face:=tile->>'face';IF strpos(seen,face)>0 THEN CONTINUE;END IF;seen:=seen||face;
    FOR letter_i IN 0..CASE WHEN face='?' THEN 25 ELSE 0 END LOOP
     letter:=CASE WHEN face='?' THEN chr(65+letter_i) ELSE face END;
     cross_word:=letter;rr:=r-CASE WHEN step_i=1 THEN 1 ELSE 0 END;cc:=c-CASE WHEN step_i=15 THEN 1 ELSE 0 END;
     WHILE rr>=0 AND cc>=0 AND board->(rr*15+cc)<>'null'::jsonb LOOP cross_word:=(board->(rr*15+cc)->>'letter')||cross_word;rr:=rr-CASE WHEN step_i=1 THEN 1 ELSE 0 END;cc:=cc-CASE WHEN step_i=15 THEN 1 ELSE 0 END;END LOOP;
     rr:=r+CASE WHEN step_i=1 THEN 1 ELSE 0 END;cc:=c+CASE WHEN step_i=15 THEN 1 ELSE 0 END;
     WHILE rr<15 AND cc<15 AND board->(rr*15+cc)<>'null'::jsonb LOOP cross_word:=cross_word||(board->(rr*15+cc)->>'letter');rr:=rr+CASE WHEN step_i=1 THEN 1 ELSE 0 END;cc:=cc+CASE WHEN step_i=15 THEN 1 ELSE 0 END;END LOOP;
     IF length(cross_word)>1 AND NOT EXISTS(SELECT 1 FROM private.ptown_words_bot_vocabulary WHERE word=cross_word) THEN CONTINUE;END IF;
     stack:=array_append(stack,jsonb_build_object('pos',next_i,'prefix',prefix||letter,'rack',remaining-tile_i,'items',placements||jsonb_build_array(jsonb_build_object('tileId',(tile->>'id')::int,'square',position_i,'letter',letter)),'connected',connected OR length(cross_word)>1 OR (empty_board AND position_i=112)));
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP search;
 IF best IS NOT NULL THEN RETURN best;END IF;
 -- One exchange attempt before passing prevents a no-word bot recycling forever.
 IF (visible->>'bagCount')::int>=7 AND coalesce((SELECT move->>'action' FROM jsonb_array_elements(visible->'moves') WITH ORDINALITY t(move,seq) WHERE move->>'playerId'=player ORDER BY seq DESC LIMIT 1),'')<>'exchange' THEN
  RETURN jsonb_build_object('action','exchange','items',(SELECT jsonb_agg(jsonb_build_object('tileId',t->'id')) FROM jsonb_array_elements(rack)t));
 END IF;
 RETURN jsonb_build_object('action','pass','items',NULL);
END $function$

CREATE OR REPLACE FUNCTION public.ptown_words_capabilities(p_session_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); allowed boolean:=private.ptown_words_actor_allowed(actor);
BEGIN
 allowed:=allowed AND EXISTS(SELECT 1 FROM private.ptown_words_release WHERE singleton AND admission_enabled);
 IF p_session_id IS NOT NULL THEN
  allowed:=allowed AND EXISTS(SELECT 1 FROM public.games WHERE id=p_session_id AND real_money IS FALSE)
   AND EXISTS(SELECT 1 FROM public.players WHERE game_id=p_session_id AND user_id=actor AND status<>'left')
   AND NOT EXISTS(SELECT 1 FROM public.players WHERE game_id=p_session_id AND status<>'left' AND NOT is_bot AND NOT private.ptown_words_actor_allowed(user_id));
 END IF;
 RETURN jsonb_build_object('version',3,'enabled',allowed,'user_id',actor,'session_id',p_session_id,'fake_money_only',true);
END $function$
